package ec.edu.espe.appdistclient.interfaz.cuentasporcobrar;
import java.awt.*;import java.time.LocalDate;import javax.swing.*;
/** Panel de prueba para simular la trama que Facturación envía al servidor. */
public class IntegracionCxcView extends JFrame{
 private final JTextField numero=new JTextField(12),fecha=new JTextField(LocalDate.now().toString(),12),cliente=new JTextField(18),identificacion=new JTextField(14),nombre=new JTextField(18),total=new JTextField(10);
 public IntegracionCxcView(){super("Integraciones | Alejandro Simba");JPanel root=new JPanel(new BorderLayout());root.setBackground(TemaCxc.BG);root.add(TemaCxc.header("INTEGRACIONES","Recepción desde Facturación y envío hacia Contabilidad"),BorderLayout.NORTH);JPanel form=new JPanel(new GridBagLayout());form.setBorder(BorderFactory.createTitledBorder("Verificar una factura existente de Facturación"));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(7,8,7,8);g.fill=GridBagConstraints.HORIZONTAL;String[] labs={"Número de factura","Fecha (AAAA-MM-DD)","Código cliente externo","Identificación cliente","Nombre cliente","Total factura"};JTextField[] fs={numero,fecha,cliente,identificacion,nombre,total};for(int i=0;i<labs.length;i++){g.gridx=0;g.gridy=i;form.add(new JLabel(labs[i]+":"),g);g.gridx=1;form.add(fs[i],g);}JButton send=new JButton("Verificar factura de Facturación");g.gridx=0;g.gridy=labs.length;g.gridwidth=2;form.add(send,g);JLabel info=new JLabel("Las facturas se consultan directamente desde Facturación en la misma base Oracle.");info.setBorder(BorderFactory.createEmptyBorder(12,8,12,8));JPanel center=new JPanel(new BorderLayout());center.setOpaque(false);center.setBorder(BorderFactory.createEmptyBorder(20,30,20,30));center.add(form,BorderLayout.NORTH);center.add(info,BorderLayout.SOUTH);root.add(center,BorderLayout.CENTER);setContentPane(root);send.addActionListener(e->receive());TemaCxc.finish(this,700,500);}
 private void receive(){try{double v=Double.parseDouble(total.getText().trim().replace(',','.'));if(v<=0)throw new NumberFormatException();String r=CxcApi.request("FACTURA","RECIBIR",numero.getText().trim(),fecha.getText().trim(),cliente.getText().trim(),identificacion.getText().trim(),nombre.getText().trim(),String.format(java.util.Locale.US,"%.2f",v));if(CxcApi.ok(r))TemaCxc.info(this,CxcApi.message(r));else TemaCxc.error(this,CxcApi.message(r));}catch(Exception ex){TemaCxc.error(this,"Verifique los datos. Total debe ser mayor a cero.");}}
}
